using DG.Tweening;
using LittleLeo;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class StarAbilityInstance : ZoomableInstance
{
	[Header("VFX")]
	[SerializeField]
	private float blinkDuration;

	[SerializeField]
	private AnimationCurve blinkCurve;

	[SerializeField]
	private float punchScaleAmount;

	[SerializeField]
	private float punchDuration;

	[SerializeField]
	private GameObject defaultVFXPrefab;

	[Header("Components")]
	[SerializeField]
	private Image starImage;

	private StarAbility starAbility;

	private float currentAngle;

	private bool overrideOrbVfx;

	private GameObject overrideOrbVfxPrefab;

	public StarAbility StarAbility => starAbility;

	public float CurrentAngle => currentAngle;

	public void SetCurrentAngle(float currentAngle)
	{
		this.currentAngle = currentAngle;
	}

	public void OnOverrideOrbVFXPrefab(GameObject overrideOrbVfxPrefab)
	{
		overrideOrbVfx = true;
		this.overrideOrbVfxPrefab = overrideOrbVfxPrefab;
	}

	public void OnResetOverrideOrbVFXPrefab()
	{
		overrideOrbVfx = false;
		overrideOrbVfxPrefab = null;
	}

	public void Initialize(StarAbility starAbility)
	{
		this.starAbility = starAbility;
		starImage.material = Object.Instantiate(starImage.material);
	}

	public override void InitializeActionDescriptionPanel()
	{
		actionDescriptionPanel.InitializeStarAbility(starAbility);
	}

	public void OnEnteringStar()
	{
		BlinkOrb();
		starAbility.OnEnteringStar();
	}

	public void OnExitingStar()
	{
		starAbility.OnExitingStar();
	}

	public void OnEndTurnStarAbility()
	{
		starAbility.OnEndTurnStarAbility();
	}

	public void OnStartTurnStarAbility()
	{
		starAbility.OnStartTurnStarAbility();
	}

	public void OnActivateStarAbility()
	{
		BlinkOrb();
		starAbility.OnActivateStarAbility();
	}

	private void BlinkOrb()
	{
		ReferenceSingleton<VFXHandler>.Instance.GetVFX(overrideOrbVfx ? overrideOrbVfxPrefab : defaultVFXPrefab, base.transform.position, 3f);
		StartCoroutine(starImage.material.TweenFloatProperty("_ColorBlend", 0f, 1f, blinkDuration, blinkCurve));
		base.transform.DOPunchScale(Vector3.one * punchScaleAmount, punchDuration);
	}
}
